<template>
  <section class="knowledge-page">
    <header class="hero">
      <div><span class="eyebrow">KNOWLEDGE OPERATIONS</span><h1>知识生产线</h1><p>从原文治理到索引、授权、引用和召回评测的一体化工作台。</p></div>
      <el-button type="primary" size="large" @click="openKnowledge()">新建知识库</el-button>
    </header>

    <div class="toolbar">
      <el-input v-model="query.keyword" clearable placeholder="知识库编码或名称" @keyup.enter="loadPage" />
      <el-select v-model="query.status" clearable placeholder="全部状态"><el-option label="草稿" value="draft" /><el-option label="启用" value="enabled" /><el-option label="停用" value="disabled" /></el-select>
      <el-button @click="loadPage">查询</el-button>
    </div>

    <div class="workspace">
      <div class="catalog">
        <button v-for="item in records" :key="item.knowledgeId" class="catalog-item" :class="{ active: detail?.knowledgeId === item.knowledgeId }" @click="selectKnowledge(item.knowledgeId)">
          <span class="status-dot" :class="item.status" /><strong>{{ item.knowledgeName }}</strong><code>{{ item.knowledgeCode }}</code>
          <small>{{ item.indexedDocumentCount }}/{{ item.documentCount }} 文档已索引</small>
        </button>
        <el-empty v-if="!records.length" description="暂无知识库" />
      </div>

      <div v-if="detail" class="detail-panel">
        <div class="detail-head"><div><h2>{{ detail.knowledgeName }}</h2><p>{{ detail.description || "暂无说明" }}</p></div><div><el-button @click="openKnowledge(detail)">编辑配置</el-button><el-button type="success" @click="createIndex">发布索引</el-button></div></div>
        <div class="metrics"><div><b>{{ detail.documents.length }}</b><span>文档</span></div><div><b>{{ detail.sources.length }}</b><span>来源</span></div><div><b>{{ detail.chunkSize }}</b><span>分块字符</span></div><div><b>{{ detail.retrievalTopK }}</b><span>Top K</span></div></div>
        <el-tabs v-model="activeTab">
          <el-tab-pane label="来源" name="sources"><div class="tab-action"><el-button type="primary" plain @click="openSource()">新增来源</el-button></div><el-table :data="detail.sources"><el-table-column prop="sourceName" label="名称" /><el-table-column prop="sourceType" label="类型" /><el-table-column prop="syncMode" label="同步" /><el-table-column prop="status" label="状态" /><el-table-column label="操作"><template #default="scope"><el-button link @click="openSource(scope.row)">编辑</el-button></template></el-table-column></el-table></el-tab-pane>
          <el-tab-pane label="文档" name="documents"><div class="tab-action"><el-button type="primary" plain @click="openDocumentUpload">上传文档</el-button></div><el-table :data="detail.documents"><el-table-column prop="documentName" label="文档" /><el-table-column prop="version" label="版本" width="80" /><el-table-column prop="contentType" label="类型" /><el-table-column prop="indexedAt" label="索引时间"><template #default="scope">{{ formatDateTime(scope.row.indexedAt, "待索引") }}</template></el-table-column><el-table-column label="操作" width="150"><template #default="scope"><el-button link type="primary" @click="previewDocument(scope.row)">预览</el-button><el-button link type="warning" :loading="reparsingDocumentId===scope.row.documentId" @click="reparseDocument(scope.row)">重新解析</el-button></template></el-table-column></el-table></el-tab-pane>
          <el-tab-pane label="权限绑定" name="bindings"><el-form label-position="top"><el-form-item label="关联 Agent"><el-select v-model="bindingAgentIds" multiple filterable><el-option v-for="item in agents" :key="item.agentId" :label="item.agentName" :value="item.agentId" /></el-select></el-form-item><el-form-item label="允许角色（不选表示关联 Agent 的所有角色可访问）"><el-select v-model="bindingRoleIds" multiple filterable><el-option v-for="item in roles" :key="item.roleId" :label="item.roleName" :value="item.roleId" /></el-select></el-form-item><el-button type="primary" @click="saveBindings">保存绑定</el-button></el-form></el-tab-pane>
          <el-tab-pane label="索引任务" name="tasks"><el-table :data="detail.indexTasks"><el-table-column prop="taskCode" label="任务" /><el-table-column prop="status" label="状态" /><el-table-column label="进度"><template #default="scope">{{ scope.row.processedDocuments }}/{{ scope.row.totalDocuments }}，{{ scope.row.totalChunks }} chunks</template></el-table-column><el-table-column prop="errorMessage" label="错误" /></el-table></el-tab-pane>
          <el-tab-pane label="分块 / 检索 / 评测" name="evaluate"><el-form label-position="top"><el-form-item label="执行 Agent"><el-select v-model="debug.agentId"><el-option v-for="item in agents" :key="item.agentId" :label="item.agentName" :value="item.agentId" /></el-select></el-form-item><el-form-item label="检索问题"><el-input v-model="debug.query" type="textarea" :rows="3" /></el-form-item><div><el-button type="primary" @click="runSearch">检索调试</el-button><el-button :loading="evalLoading" @click="runEval">按当前问题评测</el-button><el-button @click="loadChunks">查看实际分块</el-button><el-button :loading="evalHistoryLoading" @click="loadEvalRuns">评测历史</el-button></div></el-form><div v-if="evalResult" class="result"><p><b>评测完成</b>：命中 {{ evalResult.hitCaseCount }}/{{ evalResult.caseCount }}，Recall@K {{ Number(evalResult.recallAtK).toFixed(4) }}，MRR {{ Number(evalResult.meanReciprocalRank).toFixed(4) }}，平均耗时 {{ Number(evalResult.averageLatencyMs).toFixed(1) }} ms</p></div><div v-if="evalRuns" class="result"><p><b>评测历史</b>（{{ evalRuns.length }} 条）</p><el-empty v-if="!evalRuns.length" description="当前 Agent 暂无评测记录" /><el-table v-else :data="evalRuns" size="small"><el-table-column prop="runCode" label="评测编码" min-width="270" /><el-table-column label="命中" width="90"><template #default="scope">{{ scope.row.hitCaseCount }}/{{ scope.row.caseCount }}</template></el-table-column><el-table-column label="Recall@K" width="110"><template #default="scope">{{ Number(scope.row.recallAtK).toFixed(4) }}</template></el-table-column><el-table-column label="MRR" width="100"><template #default="scope">{{ Number(scope.row.meanReciprocalRank).toFixed(4) }}</template></el-table-column><el-table-column label="平均耗时" width="110"><template #default="scope">{{ Number(scope.row.averageLatencyMs).toFixed(1) }} ms</template></el-table-column><el-table-column label="创建时间" min-width="170"><template #default="scope">{{ formatDateTime(scope.row.createdAt) }}</template></el-table-column></el-table></div><div v-if="searchResult" class="result"><p>命中 {{ searchResult.hitCount }} 条，耗时 {{ searchResult.latencyMs }} ms</p><article v-for="(item, index) in searchResult.citations" :key="`${item.documentId}-${item.chunkNo}`"><b>[K{{ index + 1 }}] {{ item.documentName }}</b><span>score {{ item.score.toFixed(4) }}</span><p>{{ item.excerpt }}</p></article></div><pre v-if="chunkResult">{{ JSON.stringify(chunkResult, null, 2) }}</pre></el-tab-pane>
        </el-tabs>
      </div>
      <el-empty v-else class="detail-panel" description="选择一个知识库开始治理" />
    </div>

    <el-dialog v-model="knowledgeVisible" title="知识库配置" width="700"><el-form label-position="top"><div class="form-grid"><el-form-item label="编码"><el-input v-model="knowledgeForm.knowledgeCode" /></el-form-item><el-form-item label="名称"><el-input v-model="knowledgeForm.knowledgeName" /></el-form-item><el-form-item label="Embedding 模型"><el-select v-model="knowledgeForm.embeddingModelCode" placeholder="可空，使用运行时降级向量" clearable filterable :loading="embeddingModelsLoading" style="width:100%"><el-option v-for="model in embeddingModels" :key="model.modelCode" :label="`${model.modelName}（${model.modelCode}）`" :value="model.modelCode" /></el-select></el-form-item><el-form-item label="状态"><el-select v-model="knowledgeForm.status"><el-option label="草稿" value="draft" /><el-option label="启用" value="enabled" /><el-option label="停用" value="disabled" /></el-select></el-form-item><el-form-item label="分块大小"><el-input-number v-model="knowledgeForm.chunkSize" :min="200" :max="4000" /></el-form-item><el-form-item label="重叠长度"><el-input-number v-model="knowledgeForm.chunkOverlap" :min="0" :max="1000" /></el-form-item><el-form-item label="Top K"><el-input-number v-model="knowledgeForm.retrievalTopK" :min="1" :max="50" /></el-form-item><el-form-item label="相似度阈值"><el-input-number v-model="knowledgeForm.similarityThreshold" :min="0" :max="1" :step="0.05" /></el-form-item></div><el-form-item label="说明"><el-input v-model="knowledgeForm.description" type="textarea" /></el-form-item></el-form><template #footer><el-button @click="knowledgeVisible=false">取消</el-button><el-button type="primary" @click="saveKnowledge">保存</el-button></template></el-dialog>
    <el-dialog v-model="sourceVisible" title="知识来源" width="620"><el-form label-position="top"><el-form-item label="编码"><el-input v-model="sourceForm.sourceCode" /></el-form-item><el-form-item label="名称"><el-input v-model="sourceForm.sourceName" /></el-form-item><div class="form-grid"><el-form-item label="类型"><el-select v-model="sourceForm.sourceType"><el-option v-for="v in ['manual','url','file','database','api']" :key="v" :label="v" :value="v" /></el-select></el-form-item><el-form-item label="同步模式"><el-select v-model="sourceForm.syncMode"><el-option v-for="v in ['manual','scheduled','webhook']" :key="v" :label="v" :value="v" /></el-select></el-form-item></div><el-form-item label="来源 URI"><el-input v-model="sourceForm.sourceUri" /></el-form-item></el-form><template #footer><el-button @click="sourceVisible=false">取消</el-button><el-button type="primary" @click="saveSource">保存</el-button></template></el-dialog>
    <el-dialog v-model="documentVisible" title="上传知识文档" width="620"><el-form label-position="top"><el-form-item label="来源"><el-select v-model="documentUpload.sourceId" clearable placeholder="可选"><el-option v-for="item in detail?.sources || []" :key="item.sourceId" :label="item.sourceName" :value="item.sourceId" /></el-select></el-form-item><el-form-item label="文件"><el-upload v-model:file-list="documentFiles" drag :auto-upload="false" :limit="1" accept=".pdf,.docx,.md,.txt"><el-icon class="el-icon--upload"><UploadFilled /></el-icon><div class="el-upload__text">拖拽文件到此处，或<em>点击选择</em></div><template #tip><div class="el-upload__tip">支持 PDF、DOCX、Markdown、TXT，最大 20MB；解析后请点击“发布索引”。</div></template></el-upload></el-form-item></el-form><template #footer><el-button @click="documentVisible=false">取消</el-button><el-button type="primary" :loading="documentUploading" @click="saveDocumentUpload">上传并解析</el-button></template></el-dialog>
    <el-dialog v-model="previewVisible" :title="previewTitle" width="80%" top="5vh" destroy-on-close @closed="closeDocumentPreview"><div v-loading="previewLoading" class="document-preview"><iframe v-if="previewUrl" :src="previewUrl" :title="previewTitle" /><pre v-else-if="previewContent">{{ previewContent }}</pre><el-empty v-else-if="!previewLoading" description="没有可预览的内容" /></div></el-dialog>
  </section>
</template>

<script setup lang="ts">
import { onMounted, reactive, ref } from "vue";
import axios from "axios";
import { ElMessage, ElMessageBox } from "element-plus";
import type { UploadUserFile } from "element-plus";
import { UploadFilled } from "@element-plus/icons-vue";
import { formatDateTime } from "@/utils/dateTime";
import { createKnowledge, createKnowledgeIndexTask, evaluateKnowledge, fetchKnowledgeBindingOptions, fetchKnowledgeChunks, fetchKnowledgeDetail, fetchKnowledgeDocumentPreview, fetchKnowledgeEvalRuns, fetchKnowledgePage, reparseKnowledgeDocument, saveKnowledgeSource, searchKnowledge, updateKnowledge, updateKnowledgeBindings, uploadKnowledgeDocument } from "@/api/knowledge";
import { fetchModelPage, type ModelRecord } from "@/api/model";
import type { KnowledgeDetail, KnowledgeDocument, KnowledgePageItem, KnowledgeSource } from "@/types/knowledge";

const query = reactive({ keyword: "", status: "" });
const records = ref<KnowledgePageItem[]>([]); const detail = ref<KnowledgeDetail>(); const activeTab = ref("sources");
const agents = ref<any[]>([]); const roles = ref<any[]>([]); const bindingAgentIds = ref<number[]>([]); const bindingRoleIds = ref<number[]>([]);
const embeddingModels = ref<ModelRecord[]>([]); const embeddingModelsLoading = ref(false);
const knowledgeVisible = ref(false); const sourceVisible = ref(false); const documentVisible = ref(false);
const editingKnowledgeId = ref<number>(); const editingSourceId = ref<number>();
const knowledgeForm = reactive({ knowledgeCode:"",knowledgeName:"",description:"",embeddingModelCode:"",chunkSize:800,chunkOverlap:120,retrievalTopK:5,similarityThreshold:0.25,status:"draft",metadata:{},remark:"" });
const sourceForm = reactive({ sourceCode:"",sourceName:"",sourceType:"manual",sourceUri:"",syncMode:"manual",config:{},status:"enabled",metadata:{} });
const documentUpload = reactive({ sourceId:null as number|null }); const documentFiles = ref<UploadUserFile[]>([]); const documentUploading = ref(false);
const maxDocumentFileBytes = 20 * 1024 * 1024;
const previewVisible=ref(false); const previewLoading=ref(false); const previewTitle=ref(""); const previewContent=ref(""); const previewUrl=ref("");
const reparsingDocumentId=ref<number>();
const debug = reactive({ agentId: undefined as number|undefined, query:"", topK:5 }); const searchResult = ref<any>(); const evalResult = ref<any>(); const evalLoading=ref(false); const chunkResult = ref<any>(); const evalRuns = ref<any[]>(); const evalHistoryLoading=ref(false);

async function loadPage(){ records.value=(await fetchKnowledgePage({pageNum:1,pageSize:100,...query})).records; }
async function loadEmbeddingModels(){ embeddingModelsLoading.value=true; try{ embeddingModels.value=(await fetchModelPage({pageNum:1,pageSize:100,modelType:"embedding",status:"enabled"})).records; }catch(error){ embeddingModels.value=[]; ElMessage.error("Embedding 模型加载失败"); }finally{ embeddingModelsLoading.value=false; } }
async function selectKnowledge(id:number){ detail.value=await fetchKnowledgeDetail(id); bindingAgentIds.value=[...detail.value.agentIds]; bindingRoleIds.value=[...detail.value.roleIds]; }
async function openKnowledge(item?:KnowledgeDetail){ editingKnowledgeId.value=item?.knowledgeId; Object.assign(knowledgeForm,item?{...item,description:item.description||"",embeddingModelCode:item.embeddingModelCode||"",remark:item.remark||""}:{knowledgeCode:"",knowledgeName:"",description:"",embeddingModelCode:"",chunkSize:800,chunkOverlap:120,retrievalTopK:5,similarityThreshold:0.25,status:"draft",metadata:{},remark:""}); knowledgeVisible.value=true; await loadEmbeddingModels(); }
async function saveKnowledge(){ const saved=editingKnowledgeId.value?await updateKnowledge(editingKnowledgeId.value,knowledgeForm):await createKnowledge(knowledgeForm); knowledgeVisible.value=false; await loadPage(); await selectKnowledge(saved.knowledgeId); ElMessage.success("知识库已保存"); }
function openSource(item?:KnowledgeSource){ editingSourceId.value=item?.sourceId; Object.assign(sourceForm,item?{...item,sourceUri:item.sourceUri||""}:{sourceCode:"",sourceName:"",sourceType:"manual",sourceUri:"",syncMode:"manual",config:{},status:"enabled",metadata:{}}); sourceVisible.value=true; }
async function saveSource(){ if(!detail.value)return; detail.value=await saveKnowledgeSource(detail.value.knowledgeId,editingSourceId.value||null,sourceForm); sourceVisible.value=false; ElMessage.success("知识来源已保存"); }
function openDocumentUpload(){ documentUpload.sourceId=null; documentFiles.value=[]; documentVisible.value=true; }
async function saveDocumentUpload(){ if(!detail.value)return; const file=documentFiles.value[0]?.raw; if(!file)return ElMessage.warning("请选择要上传的文档"); if(file.size>maxDocumentFileBytes)return ElMessage.warning("上传文件不能超过 20MB"); documentUploading.value=true; try{ detail.value=await uploadKnowledgeDocument(detail.value.knowledgeId,documentUpload.sourceId,file); documentVisible.value=false; ElMessage.success("文档上传解析成功，请发布索引"); }catch(error){ ElMessage.error(documentUploadErrorMessage(error)); }finally{ documentUploading.value=false; } }
function documentUploadErrorMessage(error:unknown){ if(axios.isAxiosError(error)){ if(error.response?.status===413)return "上传文件超过网关允许的大小，请选择 20MB 以内的文件"; const data=error.response?.data as {message?:string}|undefined; if(data?.message)return data.message; if(error.code==="ECONNABORTED")return "文档上传解析超时，请稍后重试"; if(error.message==="Network Error")return "无法连接文档上传服务，请检查服务状态"; } return error instanceof Error&&error.message?error.message:"文档上传解析失败"; }
async function previewDocument(document:KnowledgeDocument){ if(!detail.value)return; closeDocumentPreview(); previewTitle.value=document.documentName; previewVisible.value=true; if(document.contentType!=="application/pdf"){ previewContent.value=document.content||""; return; } previewLoading.value=true; try{ const blob=await fetchKnowledgeDocumentPreview(detail.value.knowledgeId,document.documentId); previewUrl.value=URL.createObjectURL(blob); }catch(error){ previewVisible.value=false; ElMessage.error(documentUploadErrorMessage(error)); }finally{ previewLoading.value=false; } }
function closeDocumentPreview(){ if(previewUrl.value)URL.revokeObjectURL(previewUrl.value); previewUrl.value=""; previewContent.value=""; previewLoading.value=false; }
async function reparseDocument(document:KnowledgeDocument){ if(!detail.value)return; const confirmed=await ElMessageBox.confirm("将从原始文件重新提取正文；图片型 PDF 会执行逐页 OCR。完成后需要重新发布索引，是否继续？","重新解析文档",{type:"warning"}).then(()=>true).catch(()=>false); if(!confirmed)return; reparsingDocumentId.value=document.documentId; try{ detail.value=await reparseKnowledgeDocument(detail.value.knowledgeId,document.documentId); ElMessage.success("文档重新解析成功，请重新发布索引"); }catch(error){ ElMessage.error(documentUploadErrorMessage(error)); }finally{ reparsingDocumentId.value=undefined; } }
async function saveBindings(){ if(!detail.value)return; detail.value=await updateKnowledgeBindings(detail.value.knowledgeId,bindingAgentIds.value,bindingRoleIds.value); ElMessage.success("权限绑定已保存"); }
async function createIndex(){ if(!detail.value)return; await createKnowledgeIndexTask(detail.value.knowledgeId); await selectKnowledge(detail.value.knowledgeId); ElMessage.success("索引任务已发布"); }
async function runSearch(){ if(!detail.value||!debug.agentId||!debug.query)return ElMessage.warning("请选择 Agent 并输入问题"); searchResult.value=await searchKnowledge({agentId:debug.agentId,knowledgeId:detail.value.knowledgeId,query:debug.query,topK:debug.topK}); }
async function runEval(){ if(!detail.value||!debug.agentId||!debug.query.trim()||!detail.value.documents.length)return ElMessage.warning("需要 Agent、问题和至少一个文档"); evalLoading.value=true; evalResult.value=undefined; try{ evalResult.value=await evaluateKnowledge({agentId:debug.agentId,knowledgeId:detail.value.knowledgeId,cases:[{caseCode:"MANUAL_1",query:debug.query.trim(),expectedDocumentIds:[detail.value.documents[0].documentId],topK:debug.topK}]}); ElMessage.success("当前问题评测完成"); }catch(error){ const message=axios.isAxiosError(error)&&(error.response?.data as {message?:string}|undefined)?.message; ElMessage.error(message||"评测执行失败，请稍后重试"); }finally{ evalLoading.value=false; } }
async function loadChunks(){ if(!detail.value||!debug.agentId)return ElMessage.warning("请选择执行 Agent"); chunkResult.value=await fetchKnowledgeChunks(debug.agentId,detail.value.knowledgeId); }
async function loadEvalRuns(){ if(!debug.agentId)return ElMessage.warning("请先选择执行 Agent"); evalHistoryLoading.value=true; try{ evalRuns.value=await fetchKnowledgeEvalRuns(debug.agentId) as any[]; ElMessage.success(`已加载 ${evalRuns.value.length} 条评测记录`); }catch(error){ const message=axios.isAxiosError(error)&&(error.response?.data as {message?:string}|undefined)?.message; ElMessage.error(message||"评测历史加载失败"); }finally{ evalHistoryLoading.value=false; } }
onMounted(async()=>{ const options=await fetchKnowledgeBindingOptions(); agents.value=options.agents.map(item=>({agentId:item.id,agentName:item.name})); roles.value=options.roles.map(item=>({roleId:item.id,roleName:item.name})); await loadPage(); if(records.value[0])await selectKnowledge(records.value[0].knowledgeId); });
</script>

<style scoped>
.knowledge-page{min-width:0}.hero{display:flex;justify-content:space-between;align-items:flex-end;padding:28px 32px;border-radius:24px;background:radial-gradient(circle at 85% 10%,#d7c9a7 0,transparent 32%),linear-gradient(135deg,#14372f,#245e4e);color:#fff}.hero h1{margin:6px 0;font:700 34px Georgia,serif}.hero p{margin:0;color:#d4e7df}.eyebrow{font-size:11px;letter-spacing:2px;color:#e8c97a}.toolbar{display:grid;grid-template-columns:1fr 180px auto;gap:12px;margin:20px 0}.workspace{display:grid;grid-template-columns:260px minmax(0,1fr);gap:18px}.catalog,.detail-panel{background:#fff;border:1px solid #dce4df;border-radius:20px;padding:18px}.catalog{display:flex;flex-direction:column;gap:10px;height:fit-content}.catalog-item{text-align:left;border:1px solid #e3e9e6;background:#f8faf9;border-radius:14px;padding:14px;display:grid;grid-template-columns:12px 1fr;gap:4px 8px;color:#24433a}.catalog-item.active{border-color:#2a745e;background:#edf7f3}.catalog-item code,.catalog-item small{grid-column:2;color:#75867f}.status-dot{width:8px;height:8px;border-radius:50%;background:#999;margin-top:5px}.status-dot.enabled{background:#20a474}.detail-head{display:flex;justify-content:space-between;gap:20px}.detail-head h2{margin:0}.detail-head p{color:#74837e}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:18px 0}.metrics div{background:#f3f7f5;border-radius:14px;padding:14px;display:flex;flex-direction:column}.metrics b{font-size:24px;color:#245e4e}.metrics span{font-size:12px;color:#73827c}.tab-action{margin-bottom:12px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.document-preview{min-height:70vh}.document-preview iframe{width:100%;height:70vh;border:0}.document-preview pre{min-height:66vh;max-height:70vh;margin:0}.result article{border-top:1px solid #e4e9e7;padding:12px 0}.result article span{float:right;color:#71817b}.result article p{white-space:pre-wrap;color:#40544d}pre{white-space:pre-wrap;background:#142b26;color:#dbece5;padding:16px;border-radius:12px;overflow:auto}@media(max-width:900px){.workspace{grid-template-columns:1fr}.toolbar{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,1fr)}.form-grid{grid-template-columns:1fr}}
</style>
